def test_general(P,O):
 m=P.shape[0]-1;n=P.shape[1]-1;h,w=P.shape
 sol=[]
 for sr,sc,br,bc,er,ec in itertools.product([1,-1],[1,-1],range(h),range(h),range(w),range(w)):
  # limited form R=sr*r+br*(c//n)+er; C=sc*c+bc*(r//m)+ec (oops br h bc h)
  ok=True
  for r in range(O.shape[0]):
   for c in range(O.shape[1]):
    R=(sr*r+br*(c//n)+er)%h;C=(sc*c+bc*(r//m)+ec)%w
    if P[R,C]!=O[r,c]:ok=False;break
   if not ok:break
  if ok:sol.append((sr,sc,br,bc,er,ec))
 return sol
